low_n = 1000
high_m = 15000
limit = int(10 ** 13)
f = int(input())
inputList = []

def customFunction(i):
	if i == 0:
		return (0, 1)
	(a, b) = customFunction(i >> 1)
	(a, b) = ((2 * a * b - a * a) % low_n, (b * b + a * a) % low_n)
	if i & 1:
		(a, b) = (b % low_n, (a + b) % low_n)
	return (a, b)
i = 0
while i < high_m:
	if customFunction(i)[0] == f % low_n:
		inputList.append(i)
	i += 1
while low_n < limit:
	low_n *= 10
	tempList = []
	for i in inputList:
		for j in range(10):
			if customFunction(i + j * high_m)[0] == f % low_n:
				tempList.append(i + j * high_m)
	inputList = tempList
	high_m *= 10
	if inputList == []:
		break
if inputList == []:
	print(-1)
else:
	inputList = sorted(inputList)
	print(inputList[0])
